#!/bin/bash
set -euo pipefail

CONFIG=$1
OUT=$2
TAG=$3

# Target architecture: ARCH env overrides, otherwise the host arch. apko uses
# Alpine arch names (x86_64 / aarch64). Building the host arch is native and
# fast (e.g. aarch64 on Apple Silicon); --arch overrides the config's archs.
case "${ARCH:-$(uname -m)}" in
  amd64|x86_64)  APKO_ARCH=x86_64 ;;
  arm64|aarch64) APKO_ARCH=aarch64 ;;
  *) echo "[-] Unsupported architecture: ${ARCH:-$(uname -m)}"; exit 1 ;;
esac

rm -rf "$OUT"

# --sbom=false: this pipeline's SBOM of record is generated by syft from the
# built archive (see scripts/sbom.sh) - that's what gets scanned, policy-gated
# and signed. apko's own SBOM is redundant, and leaving it on also (a) writes a
# file to the current dir, which may be a read-only mount (e.g. a Lima VM), and
# (b) adds an SBOM attestation to the OCI index that makes the archive harder
# for buildah/docker to load. Turning it off keeps the archive a clean,
# single-image OCI tar.
echo "[+] apko build (arch: $APKO_ARCH)"
apko build --sbom=false --arch "$APKO_ARCH" "$CONFIG" "$TAG" "$OUT"
